            fatal.append(f"coverage.{field} is required [/coverage/{field}]")
            continue
        try:
            coverage_rows[field] = validate(coverage[field], text)
        except AuditError as exc:
            fatal.append(f"{exc.reason} [/coverage/{field}]")
