    assessments = coverage_rows["prior_assessments"]
    return Audit(
        tuple(validated), deepcopy(coverage), dispositions, assessments, tuple(issues),
        hashlib.sha256(text.encode("utf-8", "replace")).hexdigest(),
        _excerpt("\n".join(issues)),
